    .name("virtual-demo")
    .unstarted(() -> {
        System.out.println(Thread.currentThread().isVirtual()); // true
    });
virtualThread.start();
virtualThread.join(2000);

// lub od razu wystartowany:
Thread.ofVirtual().start(() -> { /* praca */ });

try (ExecutorService virtualExecutor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i = 0; i < 10_000; i++) {
        virtualExecutor.submit(() -> {
            Thread.sleep(50); // symulacja I/O
        });
    }
    // koniec try-with-resources -> close() czeka az wszystkie zadania sie zakoncza
}

