static long demoVirtualThreadCount(int count) throws InterruptedException {
    AtomicLong licznik = new AtomicLong(0);
    try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
        for (int i=0;i<count;i++) executor.submit(() -> { try { Thread.sleep(10); } catch (Exception e) {} licznik.incrementAndGet(); });
    }
    return licznik.get();
}
for (int n : new int[]{1000, 10_000, 100_000}) System.out.println(n+": "+demoVirtualThreadCount(n));

