static void simulateHttpServer(int requestCount) throws InterruptedException {
    long t0 = System.nanoTime();
    try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
        for (int i=0;i<requestCount;i++) {
            executor.submit(() -> {
                try { Thread.sleep(20); Thread.sleep(20); Thread.sleep(20); } catch (Exception e) {}
            });
        }
    }
    System.out.println((System.nanoTime()-t0)/1_000_000+"ms dla "+requestCount+" 'zadan http'");
}
