static Map<String,Long> loadTest(int concurrency, int durationMs) throws InterruptedException {
    AtomicLong wykonaneZadania = new AtomicLong(0);
    long deadline = System.currentTimeMillis() + durationMs;
    try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
        for (int i=0;i<concurrency;i++) {
            executor.submit(() -> {
                while (System.currentTimeMillis() < deadline) {
                    try { Thread.sleep(10); } catch (Exception e) { return; }
                    wykonaneZadania.incrementAndGet();
                }
            });
        }
    }
    return Map.of("concurrency", (long)concurrency, "zadania", wykonaneZadania.get());
}
for (int c : new int[]{100, 1000, 10000}) System.out.println(loadTest(c, 500));

AtomicInteger porazkiPodRzad = new AtomicInteger(0);
AtomicBoolean obwodOtwarty = new AtomicBoolean(false);
AtomicInteger proby = new AtomicInteger(0), sukcesy = new AtomicInteger(0), odrzucenia = new AtomicInteger(0);
Random rnd = new Random(1);
try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i=0;i<3000;i++) {
        executor.submit(() -> {
            if (obwodOtwarty.get()) { odrzucenia.incrementAndGet(); return; }
            proby.incrementAndGet();
            boolean sukces = rnd.nextDouble() >= 0.1;
            if (sukces) { porazkiPodRzad.set(0); sukcesy.incrementAndGet(); }
            else if (porazkiPodRzad.incrementAndGet() >= 5 && obwodOtwarty.compareAndSet(false, true)) {
                try { Thread.sleep(200); } catch (Exception e) {} finally { obwodOtwarty.set(false); porazkiPodRzad.set(0); }
            }
        });
    }
}
System.out.println("proby="+proby.get()+" sukcesy="+sukcesy.get()+" odrzucenia="+odrzucenia.get());

