AtomicInteger aktywne = new AtomicInteger(0), maxObserved = new AtomicInteger(0);
try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i=0;i<5000;i++) {
        executor.submit(() -> {
            int a = aktywne.incrementAndGet();
            maxObserved.updateAndGet(m -> Math.max(m,a));
            try { Thread.sleep(30); } catch (Exception e) {}
            aktywne.decrementAndGet();
        });
    }
}
System.out.println("maxObserved="+maxObserved.get()+" (bliskie 5000)");

BlockingQueue<String> zadania = new LinkedBlockingQueue<>();
String[] typy = {"A","B","C"};
Random rnd = new Random();
for (int i=0;i<10_000;i++) zadania.add(typy[rnd.nextInt(3)]);
ConcurrentHashMap<String, AtomicInteger> statystyki = new ConcurrentHashMap<>();
CountDownLatch latch = new CountDownLatch(10_000);
try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i=0;i<100;i++) {
        executor.submit(() -> {
            while (latch.getCount() > 0) {
                String typ = zadania.poll();
                if (typ == null) break;
                statystyki.computeIfAbsent(typ, k -> new AtomicInteger(0)).incrementAndGet();
                latch.countDown();
            }
        });
    }
}
latch.await(10, TimeUnit.SECONDS);
System.out.println(statystyki);
